##### a. **Add CloudWatch Metrics + X-Ray Tracing**

```ts
// src/services/UserProfileStorageService.ts

import AWS from 'aws-sdk';
import { captureAWS } from 'aws-xray-sdk-core';
import { getSegment } from 'aws-xray-sdk-core';

const s3 = captureAWS(new AWS.S3({ region: 'us-east-1' }));

export class UserProfileStorageService {
  private bucketName: string = 'user-profiles-prod-unique-id';

  async uploadProfileImage(userId: string, buffer: Buffer, contentType: string) {
    const segment = getSegment();
    const subsegment = segment?.putSubsegment('S3.Upload');

    try {
      const params = {
        Bucket: this.bucketName,
        Key: `profiles/${userId}/avatar.jpg`,
        Body: buffer,
        ContentType: contentType,
        ServerSideEncryption: 'aws:kms',
        SSEKMSKeyId: 'alias/user-profile-data-encryption',
      };

      const startTime = Date.now();
      const result = await s3.upload(params).promise();
      const durationMs = Date.now() - startTime;

      // Record custom metric
      const cloudWatch = new AWS.CloudWatch();
      await cloudWatch.putMetricData({
        Namespace: 'UserProfileService',
        MetricData: [
          {
            MetricName: 'S3UploadLatency',
            Value: durationMs,
            Unit: 'Milliseconds',
            Timestamp: new Date(),
            Dimensions: [{ Name: 'Operation', Value: 'Upload' }],
          },
        ],
      }).promise();

      subsegment?.addMetadata('S3', {
        Location: result.Location,
        Encryption: result.ServerSideEncryption,
        KMSKeyID: result.SSEKMSKeyId,
        DurationMs: durationMs,
      });

      subsegment?.close();
      return { location: result.Location, encryption: result };
    } catch (err) {
      subsegment?.addError(err);
      subsegment?.close();
      throw err;
    }
  }

  // Similar pattern for getProfileImage()
}
```

> ✅ **X-Ray + CloudWatch**: Enables observability of latency and failure patterns.  
> ✅ **Custom Metric**: Tracks P99 via CloudWatch Alarms (to be configured later).

