    throw new Error(`Failed to retrieve profile: ${err.message}`);
  }
}
```

> ✅ This avoids thread contention and improves throughput.

#### 2. **Redis Caching Layer (TTL: 5 minutes)**

Implement a cache layer with fallback to S3.

```js
const redis = require('redis').createClient({ url: 'redis://cache.prod.example.com' });

async function getCachedUserProfile(userId) {
  const cached = await redis.get(`profile:${userId}`);
  if (cached) return JSON.parse(cached);

  const profile = await getUserProfile(userId);
  await redis.setex(`profile:${userId}`, 300, JSON.stringify(profile)); // TTL: 5 min
  return profile;
}
```

> ✅ Cache hit rate should be >80% under normal load → reduces S3 calls significantly.

#### 3. **Payload Size Optimization**

Apply **field-level compression** or **selective serialization**.

##### Option A: Selective Serialization (Recommended)
Only return fields needed by frontend.

```js
// Instead of returning full profile
{
  id: "u123",
  name: "Alice",
  email: "alice@example.com",
  preferences: { theme: "dark", notifications: true },
  createdAt: "2023-01-01T00:00:00Z"
}

// Return only essential fields
{
  id: "u123",
  name: "Alice",
  email: "alice@example.com"
}
```

> ✅ Reduces average payload size from ~2KB → ~600B → ~70% savings.

##### Option B: Compression (Optional)
Use gzip compression on API responses (via API Gateway + Lambda).

```js
// In Lambda handler
const zlib = require('zlib');
const compressed = zlib.gzipSync(JSON.stringify(profile));
return {
  statusCode: 200,
  headers: { 'Content-Encoding': 'gzip' },
  body: compressed.toString('base64'),
  isBase64Encoded: true
};
```

> ⚠️ Use only if client supports decompression (most modern clients do).

